_FLAG_TENSOR_CACHE = {}


def _as_device_flag(flag, dev):
    # Fast path: a 1-element int32 device tensor is passed straight to the
    # kernels (zero host synchronization). Python bools (the aten dispatch
    # path) reuse cached device flag tensors, so no per-call H2D transfer is
    # needed. Anything else (cpu/other-dtype tensors) falls back to a one-shot
    # host read for correctness.
    if torch.is_tensor(flag):
        if flag.device == dev and flag.dtype == torch.int32:
            return flag
        value = bool(flag.item())
    else:
        value = bool(flag)
    key = (dev, value)
    cached = _FLAG_TENSOR_CACHE.get(key)
    if cached is None:
        cached = torch.tensor([1 if value else 0], dtype=torch.int32, device=dev)
        _FLAG_TENSOR_CACHE[key] = cached
    return cached


def fused_moving_avg_obs_fake_quant(
    input,
    observer_on,
    fake_quant_on,
    running_min,
    running_max,
    scale,
    zero_point,
    averaging_const,
    quant_min,
    quant_max,
    ch_axis,
    per_row_fake_quant=False,
    symmetric_quant=False,
):
    """Fused moving average observer + fake quantization (per-tensor).

    Small inputs (<= 64K elements) run as one fused single-program kernel.
    Larger inputs run three grid-capped, device-side passes with no host
    synchronization:
      1. partial min/max reduction (256 programs, grid-strided spans),
      2. single-program finalize: EMA running-stat update + scale/zero_point
         refresh (always recomputed from the running stats),
      3. grid-strided elementwise fake-quant (or plain copy when the
         fake-quant flag is off), reading scale/zero_point on the device.
    observer_on / fake_quant_on may arrive as Python bools (aten dispatch)
    or 1-element device tensors (direct calls); both are read on the device,
    so the wrapper never blocks on the accelerator.
    """
    logger.debug("GEMS_ENFLAME FUSED_MOVING_AVG_OBS_FAKE_QUANT")

    # The native ATen operator is intentionally restricted to float32 input;
    # reject anything else at the dispatch boundary instead of silently
    # converting, which would diverge from ATen.
    if input.dtype is not torch.float32:
        scalar_type = _SCALAR_TYPE_NAMES.get(input.dtype, str(input.dtype))
        raise RuntimeError(f"expected scalar type Float but found {scalar_type}")
    if per_row_fake_quant:
        raise RuntimeError(
            "per-row (per-channel) fake quant is not supported by this op; "
            "use _fused_moving_avg_obs_fq_helper instead"
        )

    x = input if input.is_contiguous() else input.contiguous()
    N = x.numel()
    if N == 0:
        return torch.empty_like(input)
    if N >= _MAX_INT32_ELEMS:
        raise RuntimeError(
            "fused_moving_avg_obs_fake_quant supports at most "
            f"{_MAX_INT32_ELEMS} elements on this backend, got {N}"
        )
    dev = x.device
    xf = x.view(-1)

    obs_flag = _as_device_flag(observer_on, dev)
    fq_flag = _as_device_flag(fake_quant_on, dev)

    qmin = int(quant_min)
    qmax = int(quant_max)
    sym = bool(symmetric_quant)
    # Symmetric-mode constants, precomputed on the host (see
    # _finalize_qparams). Python round() is round-half-to-even, matching
    # libdevice.rint.
    dneg_h = float((qmax - qmin + 1) // 2)
    dpos_h = float((qmax - qmin) // 2)
    zsym_h = float(round((qmin + qmax) * 0.5))

    out = torch.empty_like(xf)

    with torch_device_fn.device(dev):
        if N <= _SINGLE_MAX:
            _fused_small[(1,)](
                xf,
                out,
                obs_flag,
                fq_flag,
                running_min,
                running_max,
                scale,
                zero_point,
                N,
                float(averaging_const),
                qmin,
                qmax,
                dneg_h,
                dpos_h,
                zsym_h,
                SYM=sym,
                FLOOR=_SCALE_FLOOR,
                BLOCK=_REDUCE_BLOCK,
                num_warps=1,
            )
        else:
            pmin = torch.empty(_REDUCE_G, dtype=torch.float32, device=dev)
            pmax = torch.empty(_REDUCE_G, dtype=torch.float32, device=dev)
            chunk = triton.cdiv(N, _REDUCE_G)
            n_prog = min(triton.cdiv(N, _ELEM_BLOCK), _ELEM_G)
            echunk = triton.cdiv(N, n_prog)
            _minmax_partials[(_REDUCE_G,)](
                xf,
                pmin,
                pmax,
                obs_flag,
                N,
                chunk,
                BLOCK=_REDUCE_BLOCK,
                num_warps=_REDUCE_WARPS,
                num_stages=1,
            )
            _finalize_qparams[(1,)](
                pmin,
                pmax,
                running_min,
                running_max,
                scale,
                zero_point,
                obs_flag,
                _REDUCE_G,
                float(averaging_const),
                qmin,
                qmax,
                dneg_h,
                dpos_h,
                zsym_h,
                SYM=sym,
                FLOOR=_SCALE_FLOOR,
                BLOCK=_REDUCE_BLOCK,
                num_warps=4,
            )
            _fake_quant_elem[(n_prog,)](
                xf,
                out,
                fq_flag,
                scale,
                zero_point,
                N,
                echunk,
                qmin,
                qmax,
                BLOCK=_ELEM_BLOCK,
                num_warps=_ELEM_WARPS,
            )

    return out.view(input.shape)
